#!/usr/bin/env node
/**
 * Build `supabase/SETUP.sql` — the one file an operator pastes into the Supabase SQL editor.
 *
 * Why: the repository kept the base schema and the nine migrations as separate files, and every
 * new-project incident started with somebody running the wrong root-level file. There are now three
 * superseded files deleted (2026-09-12) and exactly one canonical answer: run SETUP.sql. This script
 * generates it by concatenating `KICKLIVE_FINAL_SCHEMA.sql` and `supabase/migrations/*.sql` in apply
 * order, verbatim, wrapped in BEGIN/END banners plus a `select` marker per section so a failed paste
 * names the section that failed. `--check` regenerates in memory and exits 1 on drift, which is what
 * keeps a hand-edit of SETUP.sql from silently becoming the truth; the sources are edited instead and
 * `npm run sql:bundle` re-runs.
 *
 * The output is safe to re-run over a half-applied project for the same reason each source is: every
 * statement in every section is `IF NOT EXISTS` / `CREATE OR REPLACE` / drop-then-create by name.
 */
import fs from "node:fs";
import path from "node:path";
import process from "node:process";

const REPO = path.resolve(import.meta.dirname, "..");
const OUT = path.join(REPO, "supabase", "SETUP.sql");
const check = process.argv.includes("--check");

/** The exact list and order an operator would run by hand: base schema, then migrations by filename. */
function sources() {
  const base = "KICKLIVE_FINAL_SCHEMA.sql";
  const dir = path.join(REPO, "supabase", "migrations");
  const files = fs
    .readdirSync(dir)
    .filter((f) => f.endsWith(".sql"))
    .sort();
  return [{ rel: base, abs: path.join(REPO, base) }, ...files.map((f) => ({ rel: `supabase/migrations/${f}`, abs: path.join(dir, f) }))];
}

function generate() {
  const parts = [];
  parts.push(`-- ============================================================================
-- KICKLIVE — ONE FILE TO RUN
-- ============================================================================
-- GENERATED by \`node scripts/build-sql-bundle.mjs\`; do not edit this file, edit the
-- sources and regenerate (\`npm run sql:bundle\`). \`npm run sql:bundle:check\` fails if
-- this copy and the sources disagree, so a paste from here can always be re-derived.
--
-- This is the base schema and every migration, in apply order, verbatim. A brand-new
-- Supabase project needs nothing else: run it once in the SQL editor and the database
-- is what production is supposed to look like. Re-running it over a half-applied or
-- fully-applied project is safe — every statement is idempotent by construction.
--
-- The superseded root files (SUPABASE_COMPLETE_SCHEMA.sql, SUPABASE_NEW_PROJECT_SETUP.sql,
-- supabase_migrations.sql) were deleted on 2026-09-12. They exist only in git history.
-- The admin bootstrap (CREATE_ADMIN_PROFILE.sql) is NOT part of this bundle on purpose:
-- it assumes a superuser session and names a real user; see docs/ENVIRONMENT_SETUP.md §2.
-- ============================================================================
`);
  const all = sources();
  all.forEach(({ rel, abs }, idx) => {
    const n = idx + 1;
    const body = fs.readFileSync(abs, "utf8").replace(/\s+$/, "");
    parts.push(`
-- >>> BEGIN section ${n}: ${rel} >>>
SELECT '${n} / ${all.length}: ${rel}' AS kicklive_sql_section;

${body}
;

-- <<< END section ${n}: ${rel} <<<
`);
  });
  return parts.join("");
}

const produced = generate();
if (check) {
  const onDisk = fs.existsSync(OUT) ? fs.readFileSync(OUT, "utf8") : "";
  if (onDisk !== produced) {
    console.error("sql-bundle: supabase/SETUP.sql does not match the sources — run `npm run sql:bundle`.");
    process.exit(1);
  }
  console.log(`sql-bundle: SETUP.sql is current (${sources().length} sections).`);
  process.exit(0);
}
fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, produced);
const secs = sources().length;
console.log(`sql-bundle: wrote supabase/SETUP.sql — ${secs} sections, ${produced.split("\n").length} lines.`);
